import React, { useEffect, useRef, useState } from "react";

/* ==========================================================
   SHELF HERO — /myspace, signed-out visitors
   Hosts public/landing-pages/agents-shelf.html, a derived variant
   of ThreeUI's "Complete Shelf" page (built by
   scripts/build-agents-shelf.py from the canonical source), the
   same way ThreeUI's own LandingPageFrame does: a same-origin
   iframe, sealed until loaded.

   The page talks back with postMessage ({ source: "agents-shelf" }):
     open-tool  { tool }       → onOpenTool(tool)
     scroll-by  { dy }         → the page scrolls by dy (1:1 wheel hand-off);
                                 the first one down from the top glides to
                                 belowTarget() in one move instead
     theme      { paper, paperDeep, foil, ink } → onTheme(colours)
   And the host tells the page whether it is parked at the top
   ({ source: "agents-shelf-host", type: "dock", docked }); only then
   does the shelf keep the wheel for browsing volumes.
   ========================================================== */

// Matches ThreeUI's LandingPageFrame for URL-loaded pages.
const FRAME_SANDBOX =
  "allow-downloads allow-forms allow-modals allow-popups allow-same-origin allow-scripts";

const SHELF_SRC = `${process.env.PUBLIC_URL || ""}/landing-pages/agents-shelf.html`;

// Scroll the page by exactly the forwarded wheel delta. html has
// scroll-behavior: smooth, which would turn every tick into its own
// interruptible animation (the "friction"), so it is off for the write.
const scrollPageBy = (dy) => {
  const root = document.documentElement;
  const prev = root.style.scrollBehavior;
  root.style.scrollBehavior = "auto";
  root.scrollTop += dy;
  root.style.scrollBehavior = prev;
};

// One deliberate move from the shelf to the section below it. Forwarded
// wheel input is ignored until it lands, so trackpad momentum can't restart
// it mid-way (restarts were what made it feel sticky).
const glidePageTo = (target, done) => {
  const root = document.documentElement;
  const from = root.scrollTop;
  const t0 = performance.now();
  const prev = root.style.scrollBehavior;
  root.style.scrollBehavior = "auto";
  const step = (now) => {
    const t = Math.min((now - t0) / 700, 1);
    const e = 1 - Math.pow(1 - t, 3);
    root.scrollTop = from + (target - from) * e;
    if (t < 1) requestAnimationFrame(step);
    else {
      root.style.scrollBehavior = prev;
      done();
    }
  };
  requestAnimationFrame(step);
};

export default function ShelfHero({ onOpenTool, onTheme, belowTarget }) {
  const frameRef = useRef(null);
  const [ready, setReady] = useState(false);
  const handlers = useRef({ onOpenTool, onTheme, belowTarget });
  handlers.current = { onOpenTool, onTheme, belowTarget };
  const gliding = useRef(false);

  useEffect(() => {
    const onMessage = (event) => {
      if (event.origin !== window.location.origin) return;
      if (!frameRef.current || event.source !== frameRef.current.contentWindow) return;
      const data = event.data || {};
      if (data.source !== "agents-shelf") return;
      if (data.type === "open-tool" && typeof data.tool === "string") {
        handlers.current.onOpenTool?.(data.tool);
      } else if (data.type === "theme") {
        const hex = /^#[0-9a-f]{6}$/i;
        if ([data.paper, data.paperDeep, data.foil, data.ink].every((c) => hex.test(c))) {
          handlers.current.onTheme?.({
            paper: data.paper,
            paperDeep: data.paperDeep,
            foil: data.foil,
            ink: data.ink,
          });
        }
      } else if (data.type === "scroll-by" && Number.isFinite(data.dy)) {
        if (gliding.current) return;
        const docked = document.documentElement.scrollTop <= 2;
        const target = handlers.current.belowTarget?.();
        if (docked && data.dy > 0 && Number.isFinite(target) && target > 2) {
          // Leaving the shelf: land on the section below in one move.
          gliding.current = true;
          glidePageTo(target, () => {
            // Let the tail of a trackpad fling die out before 1:1 resumes.
            setTimeout(() => {
              gliding.current = false;
            }, 250);
          });
          return;
        }
        scrollPageBy(Math.max(-400, Math.min(400, data.dy)));
      }
    };
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, []);

  // Tell the shelf whether the page is parked at the top.
  useEffect(() => {
    let raf = 0;
    let last = null;
    const report = () => {
      raf = 0;
      const docked = document.documentElement.scrollTop <= 2;
      const win = frameRef.current && frameRef.current.contentWindow;
      if (!win || docked === last) return;
      last = docked;
      win.postMessage(
        { source: "agents-shelf-host", type: "dock", docked },
        window.location.origin
      );
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(report);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    report();
    return () => {
      window.removeEventListener("scroll", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [ready]);

  return (
    <section
      className="shelf-hero"
      data-state={ready ? "ready" : "loading"}
      aria-label="Laxman's AI workspace, as a shelf of seven volumes"
    >
      <iframe
        ref={frameRef}
        title="Laxman's AI Workspace — Seven Working Systems"
        src={SHELF_SRC}
        sandbox={FRAME_SANDBOX}
        loading="eager"
        onLoad={() => setReady(true)}
      />
    </section>
  );
}
